// CSD_RATIONALE_BEGIN
// Root-cause diagnosis relative to attempt 27 (30.6% accuracy, 79.6% syntax):
//
// TWO structural bugs cause the failures:
//
// 1. mode_A (15/49 wrong): The model writes intermediate tiny spans like
//    <<n1>>, <<k_2>>, <<k_2>> during reasoning. GenerateWithPrefixAndManagedSpan
//    enters constrained mode at EVERY <<, closes tiny variable-name spans
//    (they ARE complete parses), exits, and continues. The LAST closed span is
//    the last tiny variable reference — not the full formula.
//
// 2. Unterminated (9/49): The model opens the FINAL <<int(complex_expr)>> span
//    late (~step 870), leaving only 30 steps for CloseSpanWithinBudget. Budget
//    exhausted before the closing >> is emitted.
//
// FIX: Two-phase strategy:
//   Phase 1: UnconstrainedStep loop for prefixBudget (60% = 540) steps.
//     Do NOT enter constrained mode even when << appears in the output.
//     Intermediate <<n1>>, <<k_2>> spans appear in the visible output as
//     free text but are overridden by the forced final span (evaluator takes
//     last span).
//   Phase 2: Force-open ONE constrained span with OpenConstrainedSpan.
//   Phase 3: CloseSpanWithinBudget with 360 remaining steps.
//     This is the ONLY constrained span and therefore the LAST extracted one.
//     360 steps is ample for any symbolic expression.
//
// Guidance: reinforce that int() wrapping is required and <<>> is only for
// the final formula, to steer the model's content inside the forced span.
//
// Parameters:
//   prefixBudget = 60% of maxSteps (540 of 900)
//   closeBudget  = maxSteps - steps after forced open (≥ 359 steps)
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Initialization: insideConstrainedOut := insideConstrained and
//   currentConstrainedOut := currentConstrained. The precondition guarantees
//   insideConstrained ==> parser.IsValidPrefix(currentConstrained), so the
//   invariant holds on entry.
//   Phase 1 free loop: guarded by `if !insideConstrainedOut`, so insideConstrainedOut
//   is false and unchanged throughout. currentConstrainedOut stays [] (precondition
//   ensures !insideConstrained ==> currentConstrained == []). Invariant holds vacuously.
//   Phase 2 (OpenConstrainedSpan): sets insideConstrainedOut=true and
//   currentConstrainedOut=[]. parser.IsValidPrefix([]) holds from precondition
//   `requires parser.IsValidPrefix([])`. Invariant restored.
//   Phase 3 (CloseSpanWithinBudget): its postcondition directly guarantees
//   !insideOut ==> currentOut == [] and insideOut ==> parser.IsValidPrefix(currentOut).
//   No code runs after Phase 3 that touches these variables.
//
// progress: |generated| <= |generatedPrefix| + steps  (steps used as cost proxy)
//   Phase 1 loop: each iteration increments steps by 1 and appends at most 1 token
//   to generated (EOS is not appended). So |generated| - |generatedPrefix| <= steps
//   throughout.
//   Phase 2: OpenConstrainedSpan appends exactly 1 token (<<) and we set steps+=1,
//   so the bound is preserved: (old |generated| + 1) <= |generatedPrefix| + (old steps + 1).
//   Phase 3: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + closeBudget.
//   We set steps := maxSteps = old_steps + closeBudget, so |generated| <= |generatedPrefix| + maxSteps. ✓
//   Cost bound: cost = steps <= maxSteps always.
//   Liveness (maxSteps > 0 ==> cost > 0): Phase 2 always executes when maxSteps > 0
//   (since steps < maxSteps after Phase 1 with prefixBudget < maxSteps), setting
//   steps >= 1, so cost >= 1 > 0. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm, "Solve this math problem step by step using plain text. Do NOT write << or >> during reasoning. After ALL reasoning is done, write exactly ONE final answer on the last line: <<int(symbolic_expression)>>. Inside the << >>: only bare variable names (no braces, no underscores unless in var name), integers, +, -, *, /, //, %, (, ), and int(). ALWAYS wrap in int(). Example final line: <<int(n1*p1 + n2*p2 + n3*p3)>>. Keep the expression compact and exact.");

  var steps: nat := 0;
  var prefixBudget: nat := (maxSteps * 60) / 100;

  // Phase 1: Free unconstrained generation.
  // CRITICAL: Do NOT enter constrained mode even when << appears.
  // Intermediate <<var>> tokens appear as free text and do not become the
  // last span (our forced span in Phase 2 will be last).
  if !insideConstrainedOut {
    while steps < prefixBudget
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant |generated| <= |generatedPrefix| + steps
      decreases prefixBudget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Phase 2: Force-open ONE constrained span (the single final answer span).
    if steps < maxSteps {
      var g2, ic2, cc2 := helpers.OpenConstrainedSpan(lm, generated);
      steps := steps + 1;
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
    }
  }

  // Phase 3: Close the constrained span with remaining budget.
  // 360 steps is ample to close any symbolic expression.
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci3, cc3 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci3;
    currentConstrainedOut := cc3;
    steps := maxSteps;
  }

  cost := steps;
}

